const takeRecoveryProcessLock = `-- name: TakeRecoveryProcessLock :one
SELECT pg_try_advisory_xact_lock($1::bigint) AS acquired
`

// Installation-wide fence: granted only once no serving session holds the shared lock.
func (q *Queries) TakeRecoveryProcessLock(ctx context.Context, key int64) (bool, error) {
	row := q.db.QueryRow(ctx, takeRecoveryProcessLock, key)
	var acquired bool
	err := row.Scan(&acquired)
	return acquired, err
}

